/* SCSS syntax */
.nav {
  color: blue;
}

/* Indented SASS syntax */
.nav
  color: blue

@mixin flex-center {
  display: flex;
  justify-content: center;
  align-items: center;
}

.box {
  @include flex-center;
}

/* _variables.scss */
$primary-color: red;

/* main.scss */
@use 'variables' as vars;

h1 {
  color: vars.$primary-color;
}

@mixin button-style($color) {
  background: $color;
  padding: 10px;
}

@function double($value) {
  @return $value * 2;
}

.btn {
  @include button-style(blue);
  border-width: double(1px);
}

/* styles.scss */
$color: blue;

h1 {
  color: $color;
}

/* Compile to styles.css */
/* sass styles.scss styles.css */

@use 'sass:map';

$colors: (
  primary: blue,
  secondary: green
);

.btn {
  color: map.get($colors, primary);
}

$scss-color: blue;

:root {
  --css-color: red;
}

h1 {
  color: $scss-color;
  border-color: var(--css-color);
}

@mixin button-style($color: blue) {
  background: $color;
  padding: 10px;
}

.btn-red {
  @include button-style(red);
}

.btn-default {
  @include button-style;
}
